import React from 'react';
import { useLocation } from 'react-router-dom';
import { CHANNEL_PAGE } from 'constants/urlParams';
import { parseURI } from 'util/lbryURI';
import { useAppSelector } from 'redux/hooks';
import { selectIsMarkdownPostForUri } from 'redux/selectors/content';
import { selectIsStreamPlaceholderForUri, selectChannelClaimIdForUri } from 'redux/selectors/claims';
import { selectCommentsDisabledSettingForChannelId } from 'redux/selectors/comments';
import Page from 'component/page';
import ClaimPageComponent from './internal/claimPageComponent';

type Props = {
  uri: string;
  latestContentPath?: boolean;
  liveContentPath?: boolean;
};

const ClaimPage = (props: Props) => {
  const { uri, latestContentPath, liveContentPath } = props;
  const isMarkdownPost = useAppSelector((state) => selectIsMarkdownPostForUri(state, uri));
  const isLivestreamClaim = useAppSelector((state) => selectIsStreamPlaceholderForUri(state, uri));
  const channelClaimId = useAppSelector((state) => selectChannelClaimIdForUri(state, uri));
  const chatDisabled = useAppSelector((state) => selectCommentsDisabledSettingForChannelId(state, channelClaimId));

  const { isChannel } = parseURI(uri);
  const { search, pathname } = useLocation();
  const isEmbedPath = pathname && pathname.startsWith('/$/embed');
  const ClaimRenderWrapper = React.useMemo(
    () =>
      ({ children }: { children: any }) => (
        <Page
          className="file-page"
          filePage
          isMarkdown={!!isMarkdownPost}
          noSideNavigation={isEmbedPath && !!isMarkdownPost}
        >
          {children}
        </Page>
      ),
    [isMarkdownPost, isEmbedPath]
  );
  const LivestreamPageWrapper = React.useMemo(
    () =>
      ({ children }: { children: any }) => (
        <Page className="file-page" noFooter livestream={!chatDisabled}>
          {children}
        </Page>
      ),
    [chatDisabled]
  );
  const ChannelPageWrapper = React.useMemo(
    () =>
      ({ children }: { children: any }) => (
        <Page className="channelPage-wrapper" noFooter fullWidthPage noSideNavigation={isEmbedPath}>
          {children}
        </Page>
      ),
    [isEmbedPath]
  );

  if (isChannel) {
    const urlParams = new URLSearchParams(search);
    const editing = urlParams.get(CHANNEL_PAGE.QUERIES.VIEW) === CHANNEL_PAGE.VIEWS.EDIT;

    if (editing) {
      const ChannelPageEditingWrapperLocal = ({ children }: { children: any }) => (
        <Page
          className="channelPage-wrapper channelPage-edit-wrapper"
          noFooter
          fullWidthPage
          noSideNavigation={isEmbedPath}
        >
          {children}
        </Page>
      );

      return <ClaimPageComponent uri={uri} ClaimRenderWrapper={ChannelPageEditingWrapperLocal} Wrapper={Page} />;
    }

    return (
      <ClaimPageComponent
        uri={uri}
        ClaimRenderWrapper={ChannelPageWrapper}
        Wrapper={Page}
        latestContentPath={latestContentPath}
        liveContentPath={liveContentPath}
      />
    );
  }

  if (isLivestreamClaim) {
    return <ClaimPageComponent uri={uri} ClaimRenderWrapper={LivestreamPageWrapper} Wrapper={Page} />;
  }

  return (
    <ClaimPageComponent
      uri={uri}
      ClaimRenderWrapper={ClaimRenderWrapper}
      Wrapper={Page}
      latestContentPath={latestContentPath}
      liveContentPath={liveContentPath}
    />
  );
};

export default ClaimPage;
